begin;
select plan(23);
select has_table('public','store_locations','stores are facility scoped');
select has_table('public','store_stock_items','ledger supports general store items and pharmacy lots');
select has_table('public','stock_movements','all stock changes use a movement ledger');
select has_table('public','stock_balances','on-hand values are reconciled by ledger trigger');
select has_table('public','purchase_approval_tiers','approval thresholds are configurable');
select has_table('public','goods_received_notes','goods receipt notes are recorded');
select has_table('public','supplier_returns','supplier returns are represented');
select has_table('public','supplier_performance_records','supplier performance can be recorded');
select has_column('public','pharmacy_inventory','facility_id','pharmacy lots are facility assigned for ledger use');
select has_column('public','pharmacy_inventory','store_stock_item_id','pharmacy lot quantities project from a shared store stock item');
select has_trigger('public','stock_movements','apply_stock_movement_after_insert','movement insertion updates balances atomically');
select has_trigger('public','stock_movements','stock_movements_immutable','stock ledger is append only');
select has_trigger('public','pharmacy_inventory','pharmacy_stock_ledger_guard','legacy quantity changes are captured by stock ledger');
select has_function('public','record_store_stock_movement',array['uuid','text','numeric','text','uuid','uuid','text','text'],'authorized movement RPC is available');
select has_function('public','record_store_item_movement',array['uuid','text','numeric','text','uuid','uuid','text','text'],'general store items use the same ledger');
select has_function('public','configure_purchase_approval_tier',array['uuid','numeric','numeric','integer','text'],'approval tiers are configured without defaults');
select has_function('public','receive_purchase_order',array['uuid','jsonb','text'],'partial multi-line goods receipt RPC is available');
select has_function('public','return_supplier_goods',array['uuid','text','text','jsonb'],'supplier returns issue stock through the ledger');
select ok((select count(*)=0 from public.purchase_approval_tiers),'no purchase approval thresholds are seeded');
select ok(not has_table_privilege('authenticated','public.stock_movements','INSERT'),'authenticated clients cannot write stock ledger rows directly');
select ok(exists(select 1 from pg_constraint where conrelid='public.stock_balances'::regclass and contype='c' and pg_get_constraintdef(oid) like '%quantity >= 0%'),'derived stock balance cannot go negative');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='goods_received_note_items' and policyname='procurement_child_read' and qual like '%goods_received_notes%' and qual like '%goods_received_note_id%'),'goods receipt item policy follows its note foreign key');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='supplier_return_items' and policyname='procurement_child_read' and qual like '%supplier_returns%' and qual like '%supplier_return_id%'),'supplier return item policy follows its return foreign key');
select * from finish();
rollback;
